DEFERRED={'Didache':'早期基督教文献专名，暂不列通用学习词。','didact':'独立人物名词少用，先学 didactic 与 autodidact。','negrito':'较专门的历史族群称谓，暂略。','negrita':'较专门的历史族群称谓，暂略。','negritude':'特定文化运动名称，先保留原词典资料。','denigrative':'较少用派生形容词，先掌握 denigrate 与 denigration。','denigrator':'较少用人物派生词，暂略。','nigrescence':'罕见的变黑名词，暂略。','nigrescent':'罕见的变黑形容词，暂略。','nigrine':'冷门矿物用词，暂略。','nigritude':'古旧的黑色性质词，暂略。','nigrities':'罕见的变黑、黑色名词，暂略。','squalidity':'较少用性质名词，先掌握 squalor。','ruminal':'专门解剖形容词，暂略。','ruminator':'少用人物或动物名称，暂略。','rumenic acid':'专门化学术语，暂略。','meliorism':'较专门的哲学术语，先掌握 ameliorate 与 amelioration。'}
ALREADY={'subterfuge','subterranean'}
CATALOG={r['id']:r for r in json.loads(Path('.cache/catalog.json').read_text())}
def rootwords(i,extra=()):return list(dict.fromkeys([w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED and '-' not in w]+list(extra)))
def rootexclude(i):
 r=ASSIGN['roots'][i];c=CATALOG[r['id']];return {w:DEFERRED[w] for w in set(r['family'])|set(c['family'])|set(c['words'])|set(c['unmatched']) if w in DEFERRED}
DIDA_ROOT=dict(id='C0299',meaning='教；教会；自学',core='知识从不会变成会：可以由别人教，也可以靠自己摸索。',image='希腊 didaskein → didaktos／didaktikos → didactic；英语 didactic → didacticism；autos 自己 + didaktos → autodidaktos 及相关形式 → autodidact／autodidactic。',intro='didactic 一支说教导目的，也可能嫌人说教；autodidact 一支说自学的人与方式。auto- 加上后，重点变成谁来教自己，不是自动获得知识。',forms='目录中的 da-、dida- 是历史归组写法，实际学习最有辨识度的是 didact-。英语 did 是 do 的过去式，与本根不能只按字母相连。autodidact 与 autodidactic 的重音位置不同。',branches=[['教导与说教风格','didactic, didacticism'],['自己学会','autodidact, autodidactic']],contrasts='educational 可以有教育价值却不说教；didactic 突出主动传授道理。autodidact 不等于 amateur：学习途径与职业身份是两回事。',practice='用 didactic 描述一则故事的教育目的，再用 too didactic 写说教太重；解释自学者为何也可能成为专业人士。',words=rootwords(248),exclude=rootexclude(248))
NIGR_ROOT=dict(id='C0813',meaning='黑；使变黑；贬损名誉',core='像给别人的名声涂上一层暗色，让它在别人眼里失去光彩。',image='拉丁 niger／nigr- → nigrare；de- 加强 + nigrare → denigrare；denigratus → denigrate，另一名词线 denigratio → denigration。',intro='最实用的是 denigrate 与 denigration：批评某人没价值、把成就说得一文不值。拉丁语已经有从弄黑转到名誉受损的比喻，现代通常用来说明贬低行为。',forms='niger 的词干是 nigr-，不是按英语发音删一个字母。de- 在这里加强“使黑”，不表示去除。名词 denigration 很早独立借入，不能把词族历史全画成英语动词再加词尾。',branches=[['贬损的动作','denigrate'],['贬损的过程与言辞','denigration']],contrasts='criticize 可中性地指出问题；denigrate 往往暗示不公正地轻视。不要把这个历史颜色比喻当作对任何人的肤色评价。',practice='写一句有具体理由的 criticism，再写一句将别人整项努力一概否定的 denigration，比较两者语气。',words=rootwords(249),exclude=rootexclude(249))
RAUC_ROOT=dict(id='C1207',meaning='嘶哑；粗响；喧闹',core='声音不只大，还带着扯开嗓子的粗粝感。',image='拉丁 raucus 嘶哑的 → 英语 raucous；raucous + -ly → raucously。',intro='这组词能让声音描写更具体：笑声、鸟叫、观众欢呼都可能粗响。它通常给人不安静的印象，但热闹的庆祝也可以这样写。',forms='rauc- 不是现代独立英语词；拉丁 raucus 在英语中配合 -ous 形容词形式。raucously 的 -ly 说明某人如何笑、叫、欢呼。',branches=[['声音的性质','raucous'],['发声的方式','raucously']],contrasts='loud 只说响度；hoarse 只强调嘶哑；raucous 常把粗哑和喧闹合在一起。quiet 与它相对，cheerful 却可能同时成立。',practice='分别用 raucous laughter 和 laughed raucously 改写同一个场景，感受形容词与副词怎样落在句子里。',words=rootwords(250),exclude=rootexclude(250))
IRID_ROOT=dict(id='C0613',meaning='彩虹；虹膜；虹彩',core='共同画面是颜色：眼中带色的一圈、鲜艳的花，以及表面流动的彩光。',image='希腊 iris／irid- → 拉丁 iris／irid- → 英语 iris；拉丁 irid- + -escent → iridescent → iridescence。',intro='iris 是花名和眼部名称，也能说镜头光圈；iridescent 与 iridescence 则写虹彩效果。来源相连，不表示这些东西现代必须长得完全一样。',forms='iris 的变化形式里能看见 irid-，如古典复数 irides。iridescent 应看 irid- 与 -escent，不要把末尾误拆成 descent 下降。',branches=[['眼睛、花与光圈名称','iris'],['呈现虹彩','iridescent'],['虹彩这种现象','iridescence']],contrasts='虹膜 iris 围着瞳孔 pupil；多彩 colourful 不一定会随角度变色。iridescent 不等于 fluorescent，也不表示黑暗中会自己发光。',practice='用 iris 写眼睛与花两个句子，再说明一块普通彩色布与 iridescent fabric 的区别。',words=rootwords(251),exclude=rootexclude(251))
SQUAL_ROOT=dict(id='C1400',meaning='肮脏；粗糙；破败',core='污垢与失修堆积起来，成为令人难受的整体环境。',image='拉丁 squalere 肮脏 → squalidus／法语 squalide → squalid；独立拉丁名词 squalor → 英语 squalor。',intro='squalid 形容房间、住房或卑劣的交易；squalor 说这种脏污困苦的状态。词族可以从物理环境移到道德评价，但两个层面不能自动等同。',forms='squalid 的 -id 对应古典形容词形态；squalor 是完整拉丁名词的借入。它的 -or 不表示“做某事的人”。',branches=[['环境或行为的性质','squalid'],['整体状态','squalor']],contrasts='untidy 只是没收拾整齐，squalid 强得多。poverty 是资源不足，squalor 是环境脏污破败，不能把两者当作定义相同。',practice='把 The rooms were squalid 改成包含 in squalor 的句子；再用 squalid deal 展示比喻义。',words=rootwords(252),exclude=rootexclude(252))
RUMIN_ROOT=dict(id='C1239',meaning='反刍；反复思考',core='把已经吞下的再嚼一遍；把已经想到的再想一遍。',image='拉丁 rumen／rumin- → ruminare／ruminari；分词 ruminatus → ruminate，名词 ruminatio → rumination，现在分词 ruminans → ruminant；英语 rumen 是另一次较晚借词。',intro='这一组把身体动作与心理动作连得很直观。ruminate、rumination 可说反复思量；ruminative 描述沉思气质。ruminant 是反刍动物，rumen 是其胃中的瘤胃。',forms='rumen 与 rumin- 是拉丁词形关系，不意味着英语先有 rumen 才造出其他词。-ate、-ation、-ant 各自接古典材料；词长不能拿来推断历史先后。',branches=[['脑中反复咀嚼','ruminate, rumination, ruminative'],['动物类型','ruminant'],['消化部位','rumen']],contrasts='herbivore 食草动物比 ruminant 范围大；马吃草却不反刍。一般的 rumination 可是沉思，心理学语境常指停不下来的重复思维，要看上下文。',practice='分别用 ruminate 写一头牛与一个人，再解释为什么 rumen 是部位而 rumination 是过程。',words=rootwords(253),exclude=rootexclude(253))
SANG_ROOT=dict(id='C1255',meaning='血；血缘；旧气质观念中的乐观',core='同一个“血”向三边走：血缘关系、流血暴力，以及古代有关性情的解释。',image='拉丁 sanguis／sanguin-；sanguineus 经法语等 → sanguine；sanguinarius 经法语等 → sanguinary；con- + sanguineus → consanguinitas → consanguinity。',intro='最容易混的是 sanguine 与 sanguinary：前者现代多说乐观有信心，后者说血腥或嗜血。乐观这一转变来自旧体液学说的历史观念，不是关于血量决定性格的科学结论。',forms='sanguis 的词干 sanguin- 在这些长词中较清楚。sanguine 的末尾常读 /ɡwɪn/，不是把 wine 的 /waɪn/ 搬进来。consanguinity 的重音落在 /ɡwɪ/。',branches=[['乐观与信心','sanguine'],['血腥与嗜血','sanguinary'],['共同祖先形成的血缘','consanguinity']],contrasts='sanguine 是态度，sanguinary 是暴力性质。consanguinity 说血缘，不等于因婚姻而形成的姻亲关系。',practice='用 sanguine about 描述对结果的信心；再把 sanguinary 放进历史叙述，看看二者如何因后缀不同而走向不同现代意义。',words=rootwords(254),exclude=rootexclude(254))
PRAV_ROOT=dict(id='C1114',meaning='歪；不正；使道德败坏',core='像把原本应当守住的方向扭歪，转成对道德败坏的强烈评价。',image='拉丁 pravus 不正 → depravare → 法语 depraver／英语 deprave → depraved；旧 pravity 与 deprave 的影响共同解释 depravity 的形式。',intro='deprave 是使败坏，depraved 是败坏的，depravity 是败坏这种状态或行径。三词都比普通的 bad 更重，常用于正式评论和文学叙述。',forms='de- 在这里加强，不是否定。deprave 中 /eɪ/ 与 depravity 中 /æ/ 要分别记。depravity 的来源可按 deprave 加 -ity 或较早 pravity 受动词影响改形理解。',branches=[['使品性变坏','deprave'],['败坏的性质','depraved'],['败坏的状态与行径','depravity']],contrasts='deprive、deprived、deprivation 是剥夺或缺少条件的另一族，不要因为拼写近就与道德败坏相混。',practice='比较 deprived children 与 depraved characters：一个说生活条件，一个说道德评价；再用 depravity 描述小说中的行为。',words=rootwords(255),exclude=rootexclude(255))
